"use client";

import { countryNames } from "@/lib/geo";
import DOMPurify from "dompurify";
import parse from "html-react-parser";
import * as React from "react";

export type FlagCode = keyof typeof countryNames;
type FlagSource = string | ((code: string) => string);
type ParsedFlag = {
  viewBox: string;
  children: React.ReactNode;
};
type SvgElement = React.ReactElement<React.SVGProps<SVGSVGElement>>;
interface FlagProps extends Omit<React.SVGProps<SVGSVGElement>, "children"> {
  code: FlagCode;
}

const defaultSource =
  "https://cdn.jsdelivr.net/npm/@nordaun/flags@latest/flags/{code}.svg";

const FlagContext = React.createContext<FlagSource>(defaultSource);

function FlagProvider({
  src,
  children,
}: {
  src?: FlagSource;
  children: React.ReactNode;
}) {
  return (
    <FlagContext.Provider value={src || defaultSource}>
      {children}
    </FlagContext.Provider>
  );
}

function resolveFlagUrl(src: FlagSource, code: string) {
  if (typeof src === "function") return src(code);
  const encoded = encodeURIComponent(code);
  return src.replace(/\{code\}/g, () => encoded);
}

function parseFlag(markup: string): ParsedFlag {
  const clean = DOMPurify.sanitize(markup, {
    USE_PROFILES: { svg: true, svgFilters: true },
  });

  const root = React.Children.toArray(parse(clean, { trim: true })).find(
    (node): node is SvgElement =>
      React.isValidElement(node) && node.type === "svg",
  );

  if (!root) throw new Error("Failed to parse flag: Invalid flag SVG");

  return {
    viewBox: root.props.viewBox ?? "0 0 36 36",
    children: root.props.children,
  };
}

const flagCache = new Map<string, ParsedFlag>();
const pendingFlags = new Map<string, Promise<ParsedFlag>>();

async function loadFlag(url: string): Promise<ParsedFlag> {
  const cached = flagCache.get(url);
  if (cached) return cached;

  const inflight = pendingFlags.get(url);
  if (inflight) return inflight;

  const request = (async () => {
    try {
      const response = await fetch(url);
      if (!response.ok)
        throw new Error(`Failed to load flag (${response.status}): ${url}`);

      const text = await response.text();
      const parsed = parseFlag(text);
      flagCache.set(url, parsed);
      return parsed;
    } finally {
      pendingFlags.delete(url);
    }
  })();

  pendingFlags.set(url, request);
  return request;
}

function Flag({ code, viewBox, ...props }: FlagProps) {
  const contextSource = React.useContext(FlagContext);
  const source = contextSource ?? defaultSource;

  const formattedCode = code?.toLowerCase();
  const url = formattedCode ? resolveFlagUrl(source, formattedCode) : null;

  const [, rerender] = React.useReducer((count: number) => count + 1, 0);
  const flag = url ? (flagCache.get(url) ?? null) : null;

  React.useEffect(() => {
    if (!url || flagCache.has(url)) return;

    let cancelled = false;

    async function fetchAndRender() {
      try {
        await loadFlag(url!);
        if (!cancelled) rerender();
      } catch (error) {
        console.error("Flag: Rendering failed:", error);
      }
    }

    fetchAndRender();

    return () => {
      cancelled = true;
    };
  }, [url]);

  return (
    <svg
      viewBox={viewBox ?? flag?.viewBox ?? "0 0 36 36"}
      aria-hidden
      {...props}
    >
      {flag?.children}
    </svg>
  );
}

export { Flag, FlagProvider };

"use client";

import { cn } from "cn";
import parsePhoneNumberFromString, {
  type CountryCode,
  type E164Number,
  getCountries,
  getCountryCallingCode,
} from "libphonenumber-js";
import * as React from "react";

import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Flag } from "@/components/ui/flag";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { countryNames } from "@/lib/geo";

type PhoneProps = React.ComponentProps<"input"> & {
  value?: string;
  searchPlaceholder: string;
  emptyPlaceholder: string;
};

function Phone({
  value,
  onChange,
  placeholder,
  searchPlaceholder,
  emptyPlaceholder,
  ...props
}: PhoneProps) {
  const countries: CountryCode[] = getCountries();

  const [country, setCountry] = React.useState<CountryCode>("US");
  const [number, setNumber] = React.useState<string>("");
  const [open, setOpen] = React.useState(false);

  const inputRef = React.useRef<HTMLInputElement>(null);

  const handleCountryChange = (newCountry: CountryCode) => {
    setCountry(newCountry);
    setOpen(false);
    const fullNumber = parsePhoneNumberFromString(number, newCountry);
    triggerOnChange(fullNumber?.number);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const filteredValue = e.target.value.replace(/[^0-9\-() ]/g, "");
    setNumber(filteredValue);
    const fullNumber = parsePhoneNumberFromString(filteredValue, country);
    triggerOnChange(fullNumber?.number);
  };

  const triggerOnChange = (newNumber: E164Number | undefined) => {
    if (!onChange || !inputRef.current) return;
    const syntheticEvent = {
      target: {
        ...inputRef.current,
        name: name,
        value: newNumber?.toString() ?? "",
      },
      currentTarget: inputRef.current,
    } as React.ChangeEvent<HTMLInputElement>;
    onChange(syntheticEvent);
  };

  const { name, className, ...groupProps } = props;

  return (
    <>
      <InputGroup className={cn(className)}>
        <InputGroupAddon
          align="inline-start"
          className="pl-1 my-0"
          onClick={(e) => {
            if (!e.currentTarget.contains(e.target as Node)) return;
          }}
        >
          <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger
              aria-expanded={open}
              type="button"
              role="combobox"
              className="flex flex-row gap-1.5 h-8 items-center px-2 hover:bg-accent rounded-md cursor-pointer border-0 bg-transparent"
            >
              <Flag code={country} className="size-4" />
              <InputGroupText>+{getCountryCallingCode(country)}</InputGroupText>
            </PopoverTrigger>
            <PopoverContent className="w-[320px] p-0" align="start">
              <Command>
                <CommandInput placeholder={searchPlaceholder} />
                <CommandList className="mt-1">
                  <CommandEmpty>{emptyPlaceholder}</CommandEmpty>
                  <CommandGroup>
                    {countries.map((countryCode) => (
                      <CommandItem
                        key={countryCode}
                        value={`${countryNames[countryCode]} +${getCountryCallingCode(countryCode)}`}
                        onSelect={() => handleCountryChange(countryCode)}
                        className="cursor-pointer"
                      >
                        <span className="flex flex-row gap-1.5 h-5 items-center w-full">
                          <Flag code={countryCode} className="size-5" />
                          <span className="w-10 text-end">
                            +{getCountryCallingCode(countryCode)}
                          </span>
                          <span className="text-muted-foreground flex-1">
                            {countryNames[countryCode]}
                          </span>
                          {country === countryCode && (
                            <svg
                              className="ml-auto h-4 w-4"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M5 13l4 4L19 7"
                              />
                            </svg>
                          )}
                        </span>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>
        </InputGroupAddon>
        <InputGroupInput
          ref={inputRef}
          type="tel"
          value={number}
          onChange={handleInputChange}
          placeholder={placeholder}
          {...groupProps}
        />
      </InputGroup>
      {name && <input type="hidden" name={name} value={value ?? ""} />}
    </>
  );
}

export { Phone };
